css:
html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.navegacion-planta-widget {
  --navegacion-color-texto: #758594;

  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent !important;
  pointer-events: none;
}

.navegacion-planta-widget .navegacion-planta-svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent !important;
  shape-rendering: geometricPrecision;
}

.navegacion-planta-widget .navegacion-planta-titulo {
  fill: var(--navegacion-color-texto);
  stroke: none;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 46px;
  font-weight: 700;
}

.navegacion-planta-widget,
.navegacion-planta-widget * {
  animation: none !important;
  transition: none !important;
}
